// Ubah file PDF (binary) dari Google Drive menjadi base64 untuk di-upload ke PDF.co
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const fileName = items[i].binary?.data?.fileName || 'cv.pdf';
  out.push({ json: { fileName, fileBase64: buffer.toString('base64') } });
}
return out;

// Clean HTML: bersihkan hasil konversi PDF.co (HTML) menjadi teks mentah yang rapi
const item = $input.first().json;
let html = item.body || item.html || '';
const fileName = $('Convert PDF to Base64').first().json.fileName;

let text = String(html)
  .replace(/<!--[\s\S]*?-->/g, ' ')                 // komentar HTML
  .replace(/<head[\s\S]*?<\/head>/gi, ' ')          // head + metadata
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')      // script
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')        // style
  .replace(/<meta[^>]*>/gi, ' ')                    // tag meta
  .replace(/<link[^>]*>/gi, ' ')                    // tag link
  .replace(/<\/(p|div|br|li|h[1-6]|tr)>/gi, '\n')   // jaga pemisah baris
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')                         // sisa tag HTML
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/&[a-z0-9#]+;/gi, ' ')                   // entity lain
  .replace(/[ \t]+/g, ' ')                          // spasi berlebih
  .replace(/\n\s*\n+/g, '\n')                       // baris kosong berlebih
  .trim();

// Batasi panjang agar prompt AI tetap ringan
const cleanText = text.substring(0, 12000);

return [{ json: { fileName, cleanText, charCount: cleanText.length } }];

// Parsing output JSON dari AI (Gemini) menjadi data terstruktur
const input = $input.first().json;
const fileName = $('Clean HTML').first().json.fileName;

// Ambil teks respon AI (menyesuaikan struktur output node Gemini)
let raw = input.content?.parts?.[0]?.text
  || input.candidates?.[0]?.content?.parts?.[0]?.text
  || input.text
  || input.output
  || '';

// Buang pembungkus markdown ```json jika ada, lalu ambil string JSON { ... }
raw = String(raw).replace(/```json|```/gi, '').trim();
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
let data = {};
let parseOk = true;
try {
  data = JSON.parse(raw.substring(start, end + 1));
} catch (e) {
  parseOk = false;
}

// safeArray: gabungkan array jadi string rapi, strip jika kosong
const safeArray = (arr) =>
  Array.isArray(arr) && arr.length > 0 ? arr.join(', ') : '-';

const nama = data.nama || 'Tidak diketahui';
const skill = safeArray(data.keywords);
const skor = Number.isFinite(Number(data.skor)) ? Number(data.skor) : 0;
const ringkasan = data.ringkasan || '-';

const pesan =
`📄 LAPORAN SCREENING CV BARU

👤 Nama   : ${nama}
🛠 Skill  : ${skill}
⭐ Skor   : ${skor}/100

📝 Ringkasan: ${ringkasan}

📎 File: ${fileName}${parseOk ? '' : '\n⚠️ Catatan: output AI tidak valid JSON, cek manual.'}`;

return [{ json: { nama, skill, skor, ringkasan, fileName, parseOk, pesan } }];
